package com.triathlon.prep.core;
import java.io.*;
/** Bounded private ledger payload; validation matches the existing v4 file adapter. */
public final class RecordCodec {
 private RecordCodec(){}
 private static void number(DataOutputStream out,Double n)throws IOException{out.writeBoolean(n!=null);if(n!=null)out.writeDouble(n);}
 private static Double number(DataInputStream in)throws IOException{return in.readBoolean()?in.readDouble():null;}
 public static byte[] encode(Verification.Record r)throws IOException{FileRecordStore.validate(r);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeUTF(r.sessionId);out.writeLong(r.timestamp);out.writeUTF(r.mode.name());out.writeUTF(r.maskedNumber);out.writeUTF(r.comparisonSource);out.writeUTF(r.verdict.name());out.writeUTF(r.error.name());out.writeUTF(r.liveness.name());number(out,r.score);number(out,r.threshold);out.writeBoolean(r.rule!=null);if(r.rule!=null)out.writeUTF(r.rule.name());out.writeUTF(r.algorithmVersion);out.writeUTF(r.rosterBatchId);out.writeUTF(r.membership.name());out.writeUTF(r.rosterBib);}byte[] result=bytes.toByteArray();if(result.length>1024)throw new IOException("Automatic payload too large");return result;}
 public static Verification.Record decode(byte[] bytes)throws IOException{if(bytes==null||bytes.length>1024)throw new IOException("Invalid automatic payload");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){Verification.Record r=new Verification.Record(in.readUTF(),in.readLong(),Verification.Mode.valueOf(in.readUTF()),in.readUTF(),in.readUTF(),Verification.Verdict.valueOf(in.readUTF()),Verification.Error.valueOf(in.readUTF()),Verification.Liveness.valueOf(in.readUTF()),number(in),number(in),in.readBoolean()?Verification.ScoreRule.valueOf(in.readUTF()):null,in.readUTF(),in.readUTF(),Verification.Membership.valueOf(in.readUTF()),in.readUTF());FileRecordStore.validate(r);if(in.read()!=-1)throw new IOException("Unexpected automatic payload");return r;}catch(IllegalArgumentException e){throw new IOException("Malformed automatic payload",e);}}
 public static byte[] encode(ManualRecord r)throws IOException{if(r==null)throw new IOException("Manual result required");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeUTF(r.id);out.writeLong(r.timestamp);out.writeUTF(r.mode.name());out.writeUTF(r.rosterBatchId);out.writeUTF(r.rosterBib);}byte[] result=bytes.toByteArray();if(result.length>512)throw new IOException("Manual payload too large");return result;}
 public static ManualRecord decodeManual(byte[] bytes)throws IOException{if(bytes==null||bytes.length>512)throw new IOException("Invalid manual payload");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){ManualRecord r=new ManualRecord(in.readUTF(),in.readLong(),Verification.Mode.valueOf(in.readUTF()),in.readUTF(),in.readUTF());if(in.read()!=-1)throw new IOException("Unexpected manual payload");return r;}catch(IllegalArgumentException e){throw new IOException("Malformed manual payload",e);}}
}
